import {projects,preferences,recordTask} from './state.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const writingTasks=[['topic','智能选题','◇'],['proposal','开题报告','▤'],['summary','文献综述','▥'],['writing','论文写作','✎'],['course','课程作业','▱'],['review','导师修改','♧']];
const paths={topic:'M9 18h6M10 21h4M8 14a6 6 0 1 1 8 0l-1 3H9z',proposal:'M14 3H5v18h14V8zM14 3v6h5M8 13h8m-8 4h6',summary:'M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1zm0 0v15',writing:'m15 5 4 4M4 20l4-1L20 7a3 3 0 0 0-4-4L4 15z',course:'m3 8 9-5 9 5-9 5zM6 10v6l6 3 6-3v-6',review:'M5 21v-3a7 7 0 0 1 14 0v3M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',upload:'M12 16V4m-5 5 5-5 5 5M5 12H3v9h18v-9h-2'};
const glyph=id=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.writing}"/></svg>`;
export const taskNav=id=>`<nav class="writing-task-nav" aria-label="写作任务">${writingTasks.map(([key,label])=>`<a href="#tool/${key}" class="${key===id?'selected':''}" ${key===id?'aria-current="page"':''}>${glyph(key)}${label}</a>`).join('')}</nav>`;
const chapters=['第一章　绪论','　1.1 研究背景与意义','　1.2 研究问题与研究目标','第二章　文献综述与理论基础','　2.1 相关研究进展','　2.2 理论基础','第三章　研究设计','　3.1 研究方法','　3.2 数据来源与分析思路','第四章　结果与讨论（依据实际研究填写）','第五章　结论与展望','参考文献（填写真实来源）'];
const read=()=>{try{const v=JSON.parse(localStorage.getItem('paperknow-drafts')||'[]');return Array.isArray(v)?v:[];}catch{return[];}};
export function mountWriting(draftId,projectId){const pref=preferences(),context=projects().find(p=>p.id===projectId);const loaded=read().find(d=>String(d.id)===String(draftId));let savedId=loaded?.id,content=loaded?.text||'',material=loaded?.material||'',fileName=loaded?.fileName||'',parsing=false,disposed=false,editing=false;
if(!content&&loaded?.html){const d=document.createElement('div');d.innerHTML=loaded.html;d.querySelectorAll('p,h3,h4').forEach(n=>n.append(document.createTextNode('\n')));content=d.textContent||'';}
const mode=loaded?.mode==='论文初稿'?'毕业论文':loaded?.mode||'毕业论文';
document.querySelector('.dashboard').classList.remove('category-view');document.querySelector('.dashboard').classList.add('creation-page');document.querySelector('.breadcrumb strong').textContent='研究工作台 / AI 写作';document.querySelectorAll('.sidebar .nav-link').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#category/writing'));
document.querySelector('.dashboard').innerHTML=`<div class="creation-heading"><h1>AI 写作</h1><p>从选题到成稿，按你的研究阶段开始</p></div>${taskNav('writing')}<div class="creation-grid"><section class="card creation-input"><h2>创建论文任务</h2><p class="section-hint">填写研究信息，搭建论文框架</p><form id="writing-form"><label for="writing-project">所属项目（可选）</label><select id="writing-project"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===(loaded?.projectId||projectId)?'selected':''}>${esc(p.name)}${p.status==='archived'?'（已归档）':''}</option>`).join('')}</select><fieldset class="type-field"><legend>写作类型</legend><div class="type-options">${['毕业论文','课程论文','期刊论文','SCI 论文'].map((m,i)=>`<label><input type="radio" name="writing-mode" value="${m}" ${m===mode?'checked':''}><span><i aria-hidden="true">${glyph(['course','proposal','summary','review'][i])}</i>${m}</span></label>`).join('')}</div></fieldset><div class="creation-row"><div><label for="writing-degree">学段</label><select id="writing-degree">${['专科','本科','硕士','博士','科研人员'].map(d=>`<option ${d===(loaded?.degree||context?.degree||pref.degree).replace('论文','')?'selected':''}>${d}</option>`).join('')}</select></div><div><label for="writing-major">学科专业</label><input id="writing-major" maxlength="100" value="${esc(loaded?.major??context?.major??pref.major)}" placeholder="例如：教育学"></div></div><label for="writing-title">论文题目 / 研究方向</label><div class="counted-field"><textarea id="writing-title" rows="2" maxlength="200" placeholder="例如：人工智能辅助课堂学习反馈的应用研究">${esc(loaded?.title??context?.name??'')}</textarea><span id="title-count"></span></div><label for="writing-requirements">研究要求</label><div class="counted-field"><textarea id="writing-requirements" rows="3" maxlength="2000" placeholder="填写研究重点、方法或导师要求…">${esc(loaded?.requirements||'')}</textarea><span id="requirements-count"></span></div><label for="writing-file">参考材料（可选）</label><label class="writing-upload" id="writing-drop" for="writing-file"><span class="upload-symbol" aria-hidden="true">${glyph('upload')}</span><span><b>上传文档或拖拽至此</b><small>DOCX / PDF / TXT · 最大 50MB</small></span><input id="writing-file" type="file" accept=".docx,.pdf,.txt"></label><p class="material-status" id="material-status" role="status"></p><button type="button" id="material-toggle" class="material-toggle" hidden>查看解析正文</button><div id="material-area" hidden><label for="writing-material">解析正文（可核对和编辑）</label><textarea id="writing-material" rows="5" maxlength="20000">${esc(material)}</textarea><button type="button" id="material-remove" class="material-toggle">移除参考材料</button></div><div id="writing-error" role="alert" class="error-text"></div><div class="creation-actions"><button type="button" class="btn secondary" id="writing-save">保存草稿</button><button type="submit" class="btn primary" id="writing-generate">生成论文大纲 <span aria-hidden="true">→</span></button></div><p class="creation-disclaimer">本地模板体验 · AI 服务尚未接入，参考材料不会自动分析</p></form></section><section class="card creation-output"><div class="preview-heading"><h2>论文框架预览</h2><span class="preview-tag" id="preview-tag">${content?'已保存内容':'大纲示例'}</span></div><article class="outline-paper" id="outline-paper"></article><textarea id="outline-editor" aria-label="编辑论文大纲" hidden></textarea><div class="creation-actions"><button class="btn secondary" id="outline-edit">✎　编辑大纲</button><button class="btn secondary" id="outline-export">↓　导出</button></div><button id="outline-copy" class="material-toggle" hidden>复制大纲全文</button><p id="writing-status" role="status" class="material-status"></p></section></div><div class="creation-trust">♧　引用有依据 · 内容可编辑 · 参考材料仅在当前浏览器处理</div>`;
const $=s=>document.querySelector(s),alive=()=>$('#writing-form')!==null&&!disposed;
const values=()=>({projectId:$('#writing-project').value,title:$('#writing-title').value.trim(),degree:$('#writing-degree').value,major:$('#writing-major').value.trim(),mode:$('input[name="writing-mode"]:checked')?.value||'毕业论文',requirements:$('#writing-requirements').value.trim()});
function render(){const v=values();$('#outline-paper').innerHTML=content?`<div class="outline-content">${content.split('\n').filter(Boolean).map((line,i)=>`<p class="${i===0?'outline-title':i===1?'outline-meta':line.startsWith('　')?'outline-child':/^第.+章/.test(line)?'outline-chapter':''}">${esc(line)}</p>`).join('')}</div>`:`<h3>${esc(v.title||'人工智能辅助课堂学习反馈的应用研究')}</h3><p class="outline-meta">${esc(v.degree)} · ${esc(v.major||'学科待填写')}</p><div class="outline-content">${chapters.map(l=>`<p class="${l.startsWith('　')?'outline-child':'outline-chapter'}">${esc(l)}</p>`).join('')}</div>`;$('#outline-export').disabled=!content;$('#outline-edit').disabled=!content;}
function count(){ $('#title-count').textContent=$('#writing-title').value.length+'/200';$('#requirements-count').textContent=$('#writing-requirements').value.length+'/2000';if(!content)render();}
function sync(){if(editing)content=$('#outline-editor').value;}
$('#writing-title').addEventListener('input',count);$('#writing-requirements').addEventListener('input',count);$('#writing-degree').addEventListener('change',()=>{if(!content)render();});$('#writing-major').addEventListener('input',()=>{if(!content)render();});count();render();
$('#writing-form').addEventListener('submit',e=>{e.preventDefault();if(parsing)return;const v=values();if(v.title.length<2){$('#writing-error').textContent='请填写至少 2 个字的论文题目或研究方向。';$('#writing-title').focus();return;}$('#writing-error').textContent='';content=[v.title,`${v.mode} · ${v.degree} · ${v.major||'学科待填写'}`,'',...chapters,'',v.requirements?'研究要求：'+v.requirements:'','本地大纲模板：请依据真实研究完善；未调用 AI 或分析参考材料。'].filter(Boolean).join('\n');editing=false;$('#outline-editor').hidden=true;$('#outline-paper').hidden=false;$('#outline-edit').textContent='✎　编辑大纲';$('#preview-tag').textContent='本地模板';render();$('#writing-status').textContent='大纲模板已生成，可编辑、保存和导出。';});
$('#outline-edit').addEventListener('click',()=>{if(!content)return;if(editing){sync();editing=false;render();}else{editing=true;$('#outline-editor').value=content;}$('#outline-editor').hidden=!editing;$('#outline-paper').hidden=editing;if(editing)$('#outline-editor').focus();$('#outline-edit').textContent=editing?'完成编辑':'✎　编辑大纲';});
$('#writing-save').addEventListener('click',()=>{if(parsing)return;sync();const v=values();if(v.title.length<2){$('#writing-error').textContent='保存前请填写至少 2 个字的题目或研究方向。';return;}$('#writing-error').textContent='';material=$('#writing-material').value;const item={...v,id:savedId||Date.now(),tool:'writing',updatedAt:new Date().toISOString(),text:content,html:content.split('\n').map(l=>`<p>${esc(l)}</p>`).join(''),material,fileName,stage:content?'outline':'draft',date:new Date().toLocaleString('zh-CN')};const drafts=read(),i=drafts.findIndex(d=>String(d.id)===String(item.id));if(i>=0)drafts[i]=item;else drafts.unshift(item);try{localStorage.setItem('paperknow-drafts',JSON.stringify(drafts));savedId=item.id;$('#writing-status').textContent='已保存，可在“我的成果”中继续编辑。';try{recordTask({id:'draft-'+item.id,title:item.title,kind:content?'本地大纲保存':'本地草稿保存',status:'completed',url:'#draft/'+item.id});}catch{$('#writing-status').textContent+=' 任务记录未保存。';}}catch{$('#writing-status').textContent='保存失败，浏览器空间可能不足，请先导出备份。';}});
$('#outline-export').addEventListener('click',()=>{sync();if(!content)return;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=(values().title||'论文大纲').replace(/[\\/:*?"<>|]/g,'_')+'.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);$('#outline-copy').hidden=false;$('#writing-status').textContent='已发起 TXT 下载。若浏览器未保存文件，可复制大纲全文。';});
$('#outline-copy').addEventListener('click',async()=>{sync();try{await navigator.clipboard.writeText(content);$('#writing-status').textContent='大纲已复制。';}catch{editing=true;$('#outline-editor').value=content;$('#outline-editor').hidden=false;$('#outline-paper').hidden=true;$('#outline-editor').focus();$('#outline-editor').select();$('#outline-edit').textContent='完成编辑';$('#writing-status').textContent='请使用系统复制快捷键复制已选中的大纲。';}});
async function parse(file){if(!file||parsing)return;const form=$('#writing-form');if(file.size>50*1024*1024){$('#material-status').textContent='请选择不超过 50MB 的文件。';return;}if(!/\.(docx|pdf|txt)$/i.test(file.name)){$('#material-status').textContent='仅支持 DOCX、PDF 或 UTF-8 TXT。';return;}parsing=true;$('#writing-save').disabled=true;$('#writing-generate').disabled=true;$('#material-status').textContent='正在本地解析…';try{const {extractFile}=await import('/precheck/assets/parsers.js'),r=await extractFile(file);if(!alive()||$('#writing-form')!==form){disposed=true;return;}if(!r.text.trim())throw new Error('未提取到正文；扫描 PDF 暂不支持，请转换为文本型文档。');if(r.text.length>20000)throw new Error('参考材料超过 20,000 字符，请选择较短的章节。');material=r.text;fileName=file.name;$('#writing-material').value=material;$('#material-toggle').hidden=false;$('#material-status').textContent=`${fileName} · 已解析 ${material.length} 字符${r.warnings.length?' · '+r.warnings.slice(0,2).join('；'):''}`;}catch(err){if(alive()&&$('#writing-form')===form)$('#material-status').textContent=err.message||'解析失败，请检查文件。';}finally{parsing=false;if(alive()&&$('#writing-form')===form){$('#writing-save').disabled=false;$('#writing-generate').disabled=false;$('#writing-file').value='';}}}
$('#writing-file').addEventListener('change',e=>parse(e.target.files[0]));$('#writing-drop').addEventListener('dragover',e=>{e.preventDefault();$('#writing-drop').classList.add('dragover');});$('#writing-drop').addEventListener('dragleave',()=>$('#writing-drop').classList.remove('dragover'));$('#writing-drop').addEventListener('drop',e=>{e.preventDefault();$('#writing-drop').classList.remove('dragover');if(e.dataTransfer.files.length!==1){$('#material-status').textContent='请一次选择一份参考文档。';return;}parse(e.dataTransfer.files[0]);});$('#material-toggle').addEventListener('click',()=>{$('#material-area').hidden=!$('#material-area').hidden;});$('#material-remove').addEventListener('click',()=>{material='';fileName='';$('#writing-material').value='';$('#material-area').hidden=true;$('#material-toggle').hidden=true;$('#material-status').textContent='参考材料已移除，请保存以更新草稿。';});if(material){$('#material-toggle').hidden=false;$('#material-status').textContent=`${fileName||'参考材料'} · ${material.length} 字符`;}
}
